head.b:skin:
/* -------------------------------------------------------------
 * SecureVault Pro — Diagnostic Engine Theme
 * ------------------------------------------------------------- */
#navbar-iframe { display: none !important; }

:root {
  /* Theme 0: Cyberpunk Obsidian (Default Dark) */
  --bg-main: #0B0F19;
  --surface-card: #141B2D;
  --surface-hover: #1E273E;
  --surface-border: rgba(255, 255, 255, 0.08);
  --primary: #0099FF;
  --accent: #FFD700;
  --success: #00FF88;
  --danger: #FF3366;
  --text-heading: #F8FAFC;
  --text-body: #94A3B8;
  --sidebar-width: 250px;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

[data-theme="light"] {
  /* Theme 1: Daylight Pristine (High-Contrast Light) */
  --bg-main: #F8FAFC;
  --surface-card: #FFFFFF;
  --surface-hover: #E2E8F0;
  --surface-border: rgba(0, 0, 0, 0.08);
  --primary: #1D4ED8;
  --accent: #0284C7;
  --success: #15803D;
  --danger: #DC2626;
  --text-heading: #0F172A;
  --text-body: #334155;
}

* { box-sizing: border-box; margin: 0; padding: 0; font-family: var(--font-family); }
body { background: var(--bg-main); color: var(--text-body); min-height: 100vh; transition: background 0.3s, color 0.3s; }

/* Strict View State Control Guard */
.view-state { display: none !important; }
.view-state.active { display: block !important; }

/* PRE-LOGIN SAAS LANDING PAGE STYLES */
.landing-nav { height: 80px; display: flex; align-items: center; justify-content: space-between; padding: 0 48px; max-width: 1400px; margin: 0 auto; }
.brand-logo { display: flex; align-items: center; gap: 12px; font-family: 'Space Grotesk', sans-serif; font-size: 22px; font-weight: 700; color: var(--text-heading); }

.hero-section { text-align: center; padding: 80px 20px 60px; max-width: 900px; margin: 0 auto; display: flex; flex-direction: column; align-items: center; gap: 24px; }
.hero-badge { background: rgba(0, 153, 255, 0.12); color: var(--primary); border: 1px solid rgba(0, 153, 255, 0.3); padding: 6px 16px; border-radius: 20px; font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; display: flex; align-items: center; gap: 8px; }

.hero-title { font-family: 'Space Grotesk', sans-serif; font-size: 52px; font-weight: 700; color: var(--text-heading); line-height: 1.15; letter-spacing: -1px; }
.hero-title span { background: linear-gradient(135deg, var(--primary), var(--accent)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }

.hero-subtitle { font-size: 18px; color: var(--text-body); max-width: 680px; line-height: 1.6; }
.cta-group { display: flex; gap: 16px; margin-top: 12px; flex-wrap: wrap; justify-content: center; align-items: center; }

.google-btn-hero { background: #FFFFFF; color: #1F1F1F; border: 1px solid #DADCE0; padding: 16px 32px; border-radius: 30px; font-size: 16px; font-weight: 700; cursor: pointer; display: flex; align-items: center; gap: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.15); transition: transform 0.2s, box-shadow 0.2s; }
.google-btn-hero:hover { transform: translateY(-2px); box-shadow: 0 14px 40px rgba(0,0,0,0.25); }

.download-btn-top { background: rgba(0, 255, 136, 0.12); border: 1px solid rgba(0, 255, 136, 0.3); color: var(--success); padding: 10px 20px; border-radius: 20px; font-size: 14px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 8px; transition: background 0.2s; }
.download-btn-top:hover { background: rgba(0, 255, 136, 0.2); }

.features-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; max-width: 1200px; margin: 40px auto 80px; padding: 0 20px; }
.feature-card { background: var(--surface-card); border: 1px solid var(--surface-border); border-radius: 20px; padding: 32px; display: flex; flex-direction: column; gap: 16px; box-shadow: 0 10px 30px rgba(0,0,0,0.05); }
.feature-icon { font-size: 36px; }
.feature-head { font-size: 20px; font-weight: 700; color: var(--text-heading); }
.feature-desc { font-size: 14px; color: var(--text-body); line-height: 1.6; }

/* POST-LOGIN APP DASHBOARD WORKSPACE STYLES */
.top-nav { height: 70px; background: var(--surface-card); border-bottom: 1px solid var(--surface-border); display: flex; align-items: center; justify-content: space-between; padding: 0 32px; position: sticky; top: 0; z-index: 100; backdrop-filter: blur(10px); }

.nav-brand { display: flex; align-items: center; gap: 12px; font-family: 'Space Grotesk', sans-serif; font-size: 20px; font-weight: 700; color: var(--text-heading); }
.nav-links { display: flex; gap: 24px; }
.nav-link { color: var(--text-body); text-decoration: none; font-size: 14px; font-weight: 600; cursor: pointer; transition: color 0.2s; padding: 8px 0; position: relative; }
.nav-link:hover, .nav-link.active { color: var(--primary); }
.nav-link.active::after { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 2px; background: var(--primary); border-radius: 2px; }

.nav-actions { display: flex; align-items: center; gap: 16px; }
.theme-toggle-btn { background: var(--surface-hover); border: 1px solid var(--surface-border); color: var(--text-heading); padding: 8px 16px; border-radius: 20px; font-size: 13px; font-weight: 600; cursor: pointer; transition: background 0.2s; display: flex; align-items: center; gap: 6px; }

.drive-status-badge { display: flex; align-items: center; gap: 8px; background: rgba(0, 255, 136, 0.1); border: 1px solid rgba(0, 255, 136, 0.3); color: var(--success); padding: 6px 14px; border-radius: 20px; font-size: 12px; font-weight: 600; cursor: pointer; transition: background 0.2s; }
.drive-status-badge:hover { background: rgba(0, 255, 136, 0.2); }

.user-badge { display: flex; align-items: center; gap: 10px; background: var(--surface-hover); padding: 4px 14px 4px 4px; border-radius: 24px; cursor: pointer; }
.user-avatar-img { width: 32px; height: 32px; border-radius: 50%; object-fit: cover; }
.user-avatar-circle { width: 32px; height: 32px; border-radius: 50%; background: var(--primary); color: #FFF; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 14px; }
.user-name-text { font-size: 13px; font-weight: 600; color: var(--text-heading); }

.workspace-layout { display: flex; min-height: calc(100vh - 70px); }
.sidebar-nav { width: var(--sidebar-width); background: var(--surface-card); border-right: 1px solid var(--surface-border); padding: 24px 16px; display: flex; flex-direction: column; gap: 8px; flex-shrink: 0; }
.sidebar-label { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--text-body); margin: 16px 12px 8px; }
.menu-item { display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-radius: 12px; color: var(--text-body); font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.2s; }
.menu-item:hover { background: var(--surface-hover); color: var(--text-heading); }
.menu-item.active { background: var(--primary); color: #FFFFFF; }

.main-workspace { flex: 1; padding: 32px; max-width: 1400px; margin: 0 auto; width: 100%; }
.tab-pane { display: none; }
.tab-pane.active { display: block; }

.metrics-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-bottom: 32px; }
.metric-card { background: var(--surface-card); border: 1px solid var(--surface-border); border-radius: 16px; padding: 24px; display: flex; flex-direction: column; gap: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); }
.metric-header { display: flex; align-items: center; justify-content: space-between; font-size: 13px; color: var(--text-body); font-weight: 600; }
.metric-val { font-size: 28px; font-weight: 700; color: var(--text-heading); font-family: 'Space Grotesk', sans-serif; }
.metric-sub { font-size: 12px; color: var(--success); font-weight: 600; }

.workspace-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 24px; flex-wrap: wrap; gap: 16px; }
.workspace-title { font-size: 24px; font-weight: 700; color: var(--text-heading); }

.action-bar { display: flex; gap: 12px; align-items: center; }
.search-input { background: var(--surface-card); border: 1px solid var(--surface-border); padding: 10px 16px; border-radius: 10px; color: var(--text-heading); outline: none; font-size: 14px; width: 260px; }

.btn-primary { background: var(--primary); color: #FFFFFF; border: none; padding: 10px 20px; border-radius: 10px; font-size: 14px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 8px; transition: opacity 0.2s; }
.btn-primary:hover { opacity: 0.9; }
.btn-secondary { background: var(--surface-hover); color: var(--text-heading); border: 1px solid var(--surface-border); padding: 10px 20px; border-radius: 10px; font-size: 14px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 8px; }

.table-container { background: var(--surface-card); border: 1px solid var(--surface-border); border-radius: 16px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.05); }
.data-table { width: 100%; border-collapse: collapse; text-align: left; font-size: 14px; }
.data-table th { background: var(--surface-hover); color: var(--text-body); font-weight: 600; padding: 16px 24px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
.data-table td { padding: 18px 24px; border-bottom: 1px solid var(--surface-border); color: var(--text-heading); }
.data-table tr:last-child td { border-bottom: none; }
.data-table tr:hover td { background: var(--surface-hover); }

.table-actions { display: flex; gap: 8px; }
.tbl-btn { background: transparent; border: 1px solid var(--surface-border); color: var(--text-heading); padding: 6px 12px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 4px; }
.tbl-btn:hover { border-color: var(--primary); color: var(--primary); }

.modal-backdrop { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.7); backdrop-filter: blur(6px); display: none; align-items: center; justify-content: center; z-index: 300; padding: 20px; }
.modal-backdrop.active { display: flex; }
.modal-box { background: var(--surface-card); border: 1px solid var(--surface-border); border-radius: 20px; padding: 32px; width: 100%; max-width: 520px; box-shadow: 0 20px 50px rgba(0,0,0,0.3); display: flex; flex-direction: column; gap: 20px; }
.modal-head { font-size: 20px; font-weight: 700; color: var(--text-heading); }

.form-group { display: flex; flex-direction: column; gap: 8px; }
.form-label { font-size: 12px; font-weight: 600; color: var(--text-body); }
.form-input { background: var(--bg-main); border: 1px solid var(--surface-border); padding: 12px; border-radius: 10px; color: var(--text-heading); outline: none; font-size: 14px; }

.totp-card { background: var(--bg-main); border: 1px solid var(--surface-border); border-radius: 16px; padding: 24px; display: flex; align-items: center; justify-content: space-between; margin-bottom: 24px; }
.totp-code-val { font-family: 'Space Grotesk', sans-serif; font-size: 32px; font-weight: 700; color: var(--primary); letter-spacing: 6px; }
.totp-ring-timer { font-size: 16px; font-weight: 700; color: var(--accent); }

/* Diagnostic Console Panel */
.diagnostic-panel { background: #050811; border: 1px solid var(--primary); border-radius: 16px; padding: 20px; margin-bottom: 32px; font-family: 'Space Grotesk', monospace; font-size: 12px; color: #00FF88; max-height: 240px; overflow-y: auto; box-shadow: 0 10px 30px rgba(0,0,0,0.4); }
.diag-line { margin-bottom: 4px; line-height: 1.5; }
.diag-line.err { color: #FF3366; }
.diag-line.warn { color: #FFD700; }

@media (max-width: 992px) {
  .workspace-layout { flex-direction: column; }
  .sidebar-nav { width: 100%; border-right: none; border-bottom: 1px solid var(--surface-border); padding: 12px 20px; flex-direction: row; overflow-x: auto; }
  .metrics-grid { grid-template-columns: repeat(2, 1fr); }
  .top-nav, .landing-nav { padding: 0 20px; }
  .nav-links { display: none; }
  .features-grid { grid-template-columns: 1fr; }
  .hero-title { font-size: 36px; }
}

body.script:
//
  let webVault = [];
  let totpTimeLeft = 30;
  let gDriveAccessToken = null;
  let gDriveFileId = localStorage.getItem('secure_vault_gdrive_file_id') || null;
  let detectedDriveFiles = [];

  const GOOGLE_CLIENT_ID = "10151634026-hk92m5ur24ffogfno23qabm7e6tageca.apps.googleusercontent.com";

  // WebCrypto PBKDF2 + AES-GCM Key Derivation & Decryption / Encryption
  async function deriveWebKey(passwordStr, saltBytes) {
    const enc = new TextEncoder();
    const passwordKey = await crypto.subtle.importKey(
      'raw',
      enc.encode(passwordStr),
      { name: 'PBKDF2' },
      false,
      ['deriveKey']
    );
    return await crypto.subtle.deriveKey(
      {
        name: 'PBKDF2',
        salt: saltBytes,
        iterations: 600000,
        hash: 'SHA-256'
      },
      passwordKey,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );
  }

  async function decryptWebPayload(encryptedBlob, passwordStr, saltBytes) {
    const parts = encryptedBlob.trim().split('.');
    if (parts.length !== 2) throw new Error('Invalid format');
    const iv = Uint8Array.from(atob(parts[0]), function(c) { return c.charCodeAt(0); });
    const ciphertext = Uint8Array.from(atob(parts[1]), function(c) { return c.charCodeAt(0); });
    const key = await deriveWebKey(passwordStr, saltBytes);
    const decryptedBuffer = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: iv },
      key,
      ciphertext
    );
    return new TextDecoder('utf-8').decode(decryptedBuffer);
  }

  async function encryptWebPayload(jsonStr, passwordStr, saltBytes) {
    const enc = new TextEncoder();
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const key = await deriveWebKey(passwordStr, saltBytes);
    const encryptedBuffer = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv: iv },
      key,
      enc.encode(jsonStr)
    );
    const ivB64 = btoa(String.fromCharCode.apply(null, iv));
    const ctB64 = btoa(String.fromCharCode.apply(null, new Uint8Array(encryptedBuffer)));
    return ivB64 + '.' + ctB64;
  }

  function logDiag(msg, type) {
    if (!type) type = 'info';
    const consoleEl = document.getElementById('diagConsole');
    if (consoleEl) {
      const line = document.createElement('div');
      line.className = 'diag-line ' + (type === 'err' ? 'err' : type === 'warn' ? 'warn' : '');
      line.innerText = '[' + new Date().toLocaleTimeString() + '] ' + msg;
      consoleEl.appendChild(line);
      consoleEl.scrollTop = consoleEl.scrollHeight;
    }
    console.log(msg);
  }

  function checkAuthSession() {
    const savedUser = localStorage.getItem('secure_vault_user_session');
    if (savedUser) {
      try {
        const user = JSON.parse(savedUser);
        activateDashboard(user);
      } catch(e) { lockAppView(); }
    } else {
      lockAppView();
    }
  }

  function lockAppView() {
    document.getElementById('landingView').classList.add('active');
    document.getElementById('appDashboardView').classList.remove('active');
  }

  function activateDashboard(user) {
    document.getElementById('landingView').classList.remove('active');
    document.getElementById('appDashboardView').classList.add('active');

    const avatarEl = document.getElementById('userAvatar');
    if (user.avatar && user.avatar.length > 5) {
      avatarEl.innerHTML = '<img src="' + user.avatar + '" class="user-avatar-img"/>';
    } else {
      avatarEl.innerText = (user.name || user.email || 'S').charAt(0).toUpperCase();
    }

    document.getElementById('userNameText').innerText = user.name || user.email || 'sharyar1670@gmail.com';

    initDatabase();
    startTotpTimer();

    if (user.accessToken) {
      gDriveAccessToken = user.accessToken;
      scanAndRestoreExactAndroidAppBackup();
    }
  }

  function triggerDirectGoogleOAuth() {
    logDiag("Initiating Google OAuth Client (GIS Web SDK)...");
    showWebToast('Connecting to Google (If warned, click Advanced -> Go to unsafe)');

    if (window.google && google.accounts && google.accounts.oauth2) {
      const client = google.accounts.oauth2.initTokenClient({
        client_id: GOOGLE_CLIENT_ID,
        scope: 'https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/userinfo.email https://www.googleapis.com/auth/drive.appdata https://www.googleapis.com/auth/drive.file https://www.googleapis.com/auth/drive.readonly',
        callback: function(tokenResponse) {
          if (tokenResponse && tokenResponse.access_token) {
            gDriveAccessToken = tokenResponse.access_token;
            logDiag("OAuth token acquired successfully. Access token length: " + gDriveAccessToken.length);

            fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
              headers: { Authorization: 'Bearer ' + tokenResponse.access_token }
            })
            .then(function(res) { return res.json(); })
            .then(function(profile) {
              logDiag("Authenticated Profile: " + profile.email);
              const user = {
                name: profile.name || profile.given_name || profile.email.split('@')[0],
                email: profile.email,
                avatar: profile.picture || profile.name.charAt(0).toUpperCase(),
                accessToken: tokenResponse.access_token
              };
              localStorage.setItem('secure_vault_user_session', JSON.stringify(user));
              activateDashboard(user);
            }).catch(function(e) {
              logDiag("UserInfo fetch failed: " + e.message, 'warn');
              authenticateDirectUserSession();
            });
          }
        }
      });
      client.requestAccessToken();
    } else {
      logDiag("GIS SDK not loaded in browser, attempting fallback...", 'warn');
      authenticateDirectUserSession();
    }
  }

  function authenticateDirectUserSession() {
    const sessionUser = { name: 'Sharyar', email: 'sharyar1670@gmail.com', avatar: 'S' };
    localStorage.setItem('secure_vault_user_session', JSON.stringify(sessionUser));
    activateDashboard(sessionUser);
  }

  function scanAndRestoreExactAndroidAppBackup() {
    if (!gDriveAccessToken) {
      logDiag("No active OAuth access token available.", 'err');
      triggerDirectGoogleOAuth();
      return;
    }

    logDiag("Querying Google Drive API v3: spaces=appDataFolder ...");
    updateDriveBadge('Scanning AppData...', '#FFD700');

    fetch("https://www.googleapis.com/drive/v3/files?spaces=appDataFolder&fields=files(id,name,mimeType,modifiedTime,size)&pageSize=100", {
      headers: { Authorization: 'Bearer ' + gDriveAccessToken }
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
      detectedDriveFiles = data.files || [];
      logDiag('Google Drive API returned ' + detectedDriveFiles.length + ' file(s) in AppData.');

      const selectEl = document.getElementById('gDriveFileSelect');

      if (detectedDriveFiles.length > 0) {
        detectedDriveFiles.sort(function(a,b) { return new Date(b.modifiedTime) - new Date(a.modifiedTime); });

        detectedDriveFiles.forEach(function(f) {
          logDiag(' -> File: "' + f.name + '" | ID: ' + f.id + ' | Size: ' + (f.size || 'AppData') + ' | Modified: ' + f.modifiedTime);
        });

        selectEl.innerHTML = detectedDriveFiles.map(function(f) {
          const dateStr = new Date(f.modifiedTime).toLocaleString();
          return '<option value="' + f.id + '"> ' + f.name + ' (' + dateStr + ')</option>';
        }).join('');

        const target = detectedDriveFiles.find(function(f) { return f.name === "vault_backup.enc" || f.name.includes("secure_vault") || f.name.includes("vault"); });
        if (target) {
          logDiag('Auto-selected target backup file: "' + target.name + '" (ID: ' + target.id + ')');
          gDriveFileId = target.id;
          localStorage.setItem('secure_vault_gdrive_file_id', target.id);
          selectEl.value = target.id;
          downloadAndParseMobileBackupPayload(target.id, target.name);
        } else {
          downloadAndParseMobileBackupPayload(detectedDriveFiles[0].id, detectedDriveFiles[0].name);
        }
      } else {
        logDiag("Zero files in AppData space. Fallback checking root drive...", 'warn');
        fetch("https://www.googleapis.com/drive/v3/files?spaces=drive&q=name='vault_backup.enc'&fields=files(id,name,mimeType,modifiedTime,size)&pageSize=50", {
          headers: { Authorization: 'Bearer ' + gDriveAccessToken }
        })
        .then(function(r) { return r.json(); })
        .then(function(rootData) {
          const rootFiles = rootData.files || [];
          if (rootFiles.length > 0) {
            detectedDriveFiles = rootFiles;
            selectEl.innerHTML = rootFiles.map(function(f) {
              return '<option value="' + f.id + '"> ' + f.name + ' (' + new Date(f.modifiedTime).toLocaleString() + ')</option>';
            }).join('');
            gDriveFileId = rootFiles[0].id;
            localStorage.setItem('secure_vault_gdrive_file_id', rootFiles[0].id);
            downloadAndParseMobileBackupPayload(rootFiles[0].id, rootFiles[0].name);
          } else {
            logDiag("Zero backup files found across Drive.", 'warn');
            selectEl.innerHTML = '<option value="">No backup files found on Google Drive</option>';
            updateDriveBadge('Clean Vault Ready', '#00FF88');
          }
        });
      }
    })
    .catch(function(err) {
      logDiag("Drive API Error: " + err.message, 'err');
    });
  }

  function loadSelectedGoogleDriveFile() {
    const selectEl = document.getElementById('gDriveFileSelect');
    const fileId = selectEl.value;
    if (!fileId) return;
    const fileObj = detectedDriveFiles.find(function(f) { return f.id === fileId; });
    downloadAndParseMobileBackupPayload(fileId, fileObj ? fileObj.name : 'Selected File');
  }

  function downloadAndParseMobileBackupPayload(fileId, fileName) {
    gDriveFileId = fileId;
    localStorage.setItem('secure_vault_gdrive_file_id', fileId);
    logDiag('Fetching "' + fileName + '" (ID: ' + fileId + ')...');
    fetch('https://www.googleapis.com/drive/v3/files/' + fileId + '?alt=media', {
      headers: { Authorization: 'Bearer ' + gDriveAccessToken }
    })
    .then(function(res) { return res.arrayBuffer(); })
    .then(async function(buffer) {
      var rawContent = new TextDecoder('utf-8').decode(buffer);
      logDiag('Downloaded ' + rawContent.length + ' chars from "' + fileName + '".');
      try {
        var trimmed = rawContent.trim();
        var parsed = null;

        if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
          parsed = JSON.parse(trimmed);
          logDiag('Parsed plain JSON payload successfully.');
        } else if (trimmed.includes('.')) {
          logDiag('Encrypted AES-GCM payload detected. Attempting WebCrypto decryption...');
          const userEmail = (JSON.parse(localStorage.getItem('secure_vault_user_session') || '{}')).email || 'sharyar1670@gmail.com';

          var saltBytes = null;
          const saltFile = detectedDriveFiles.find(function(f) { return f.name === 'key.salt'; });
          if (saltFile) {
            const saltRes = await fetch('https://www.googleapis.com/drive/v3/files/' + saltFile.id + '?alt=media', {
              headers: { Authorization: 'Bearer ' + gDriveAccessToken }
            });
            const saltBuf = await saltRes.arrayBuffer();
            saltBytes = new Uint8Array(saltBuf);
            logDiag('Downloaded key.salt (' + saltBytes.length + ' bytes).');
          }
          if (!saltBytes || saltBytes.length !== 32) {
            saltBytes = new TextEncoder().encode(userEmail.padEnd(32, '0').slice(0, 32));
          }

          try {
            const decryptedText = await decryptWebPayload(trimmed, userEmail, saltBytes);
            parsed = JSON.parse(decryptedText);
            logDiag('WebCrypto AES-256-GCM Decryption SUCCESSFUL!');
          } catch (decryptErr) {
            logDiag('WebCrypto Decryption failed: ' + decryptErr.message, 'warn');
          }
        }

        if (parsed) {
          logDiag('JSON OK. Root keys: ' + Object.keys(parsed).join(', '));
          logDiag('Backup version: ' + (parsed.version || 'unknown'));
          var restoredEntries = [];
          if (parsed.entries && Array.isArray(parsed.entries)) {
            restoredEntries = parsed.entries;
            logDiag('Found "entries": ' + restoredEntries.length + ' items.');
          } else if (Array.isArray(parsed)) {
            restoredEntries = parsed;
          } else if (parsed.items && Array.isArray(parsed.items)) {
            restoredEntries = parsed.items;
          }
          var restoredTotps = (parsed.totps && Array.isArray(parsed.totps)) ? parsed.totps : [];
          logDiag('TOTP accounts: ' + restoredTotps.length);

          if (restoredEntries.length > 0) {
            var emojiMap = {
              WEBSITES: '🌐', APPS: '📱', BANKING: '🏦',
              CRYPTO: '🪙', SOCIAL: '💬', WORK: '💼',
              EMAIL: '📧', OTHER: '🔐'
            };
            webVault = restoredEntries.map(function(e) {
              var cat = (e.category || 'WEBSITES').toUpperCase();
              return {
                id: e.id || String(Date.now() + Math.random()),
                title: e.title || e.serviceName || e.name || 'Vault Entry',
                username: e.username || e.loginId || '',
                email: e.email || '',
                website: e.website || e.url || '',
                password: e.password || '',
                notes: e.notes || '',
                category: cat,
                emoji: e.emoji || emojiMap[cat] || '🔐',
                isFavorite: e.isFavorite || false,
                strengthScore: e.strengthScore || 0,
                createdAt: e.createdAt || Date.now(),
                updatedAt: e.updatedAt || Date.now()
              };
            });
            saveWebDB(false);
            renderTables();
            updateDriveBadge('☁️ ' + webVault.length + ' Entries Restored', '#00FF88');
            logDiag('🎉 RESTORE SUCCESS: ' + webVault.length + ' vault entries + ' + restoredTotps.length + ' 2FA tokens!');
            showWebToast('Restored ' + webVault.length + ' entries from "' + fileName + '"!');
          } else {
            logDiag('0 entries in "' + fileName + '". Check backup file.', 'warn');
            updateDriveBadge('⚠️ No entries in selected file', '#FFD700');
          }
        } else {
          updateDriveBadge('❌ Decryption Failed', '#FF3366');
        }
      } catch(ex) {
        logDiag('Parse error: ' + ex.message, 'err');
        updateDriveBadge('❌ Parse Error', '#FF3366');
      }
    })
    .catch(function(err) { logDiag('Drive fetch error: ' + err.message, 'err'); });
  }

  async function createCloudBackupNow() {
    if (!gDriveAccessToken) {
      triggerDirectGoogleOAuth();
      return;
    }

    logDiag("Creating Android-compatible BackupPayload JSON...");
    const entries = webVault.map(function(e) {
      return {
        id: e.id, title: e.title || '', username: e.username || '',
        email: e.email || '', password: e.password || '',
        website: e.website || '', url: e.website || '',
        notes: e.notes || '', category: e.category || 'WEBSITES',
        customFieldsJson: '[]', tagsJson: '[]',
        isFavorite: e.isFavorite || false, hasTotp: false, totpSecret: '',
        createdAt: e.createdAt || Date.now(), updatedAt: e.updatedAt || Date.now(),
        lastAccessedAt: null, expiresAt: null,
        strengthScore: e.strengthScore || 0, deletedAt: null, isHiddenInTravel: false
      };
    });
    const payload = { version: 3, entries: entries, notes: [], cards: [], totps: [], contacts: [] };
    const jsonStr = JSON.stringify(payload, null, 2);

    const userEmail = (JSON.parse(localStorage.getItem('secure_vault_user_session') || '{}')).email || 'sharyar1670@gmail.com';
    var saltBytes = new Uint8Array(32);
    crypto.getRandomValues(saltBytes);
    var uploadBlob = jsonStr;
    try {
      uploadBlob = await encryptWebPayload(jsonStr, userEmail, saltBytes);
      logDiag("Encrypted payload with WebCrypto AES-GCM 256!");

      // Also upload key.salt (32 bytes) so Android can derive the key
      const saltMetadata = { name: 'key.salt', parents: ['appDataFolder'], mimeType: 'application/octet-stream' };
      const saltForm = new FormData();
      saltForm.append('metadata', new Blob([JSON.stringify(saltMetadata)], { type: 'application/json' }));
      saltForm.append('file', new Blob([saltBytes], { type: 'application/octet-stream' }));

      const existingSalt = detectedDriveFiles.find(function(f) { return f.name === 'key.salt'; });
      if (existingSalt) {
        fetch('https://www.googleapis.com/upload/drive/v3/files/' + existingSalt.id + '?uploadType=media', {
          method: 'PATCH',
          headers: { Authorization: 'Bearer ' + gDriveAccessToken, 'Content-Type': 'application/octet-stream' },
          body: saltBytes
        });
      } else {
        fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart', {
          method: 'POST',
          headers: { Authorization: 'Bearer ' + gDriveAccessToken },
          body: saltForm
        });
      }
    } catch (e) {
      logDiag("WebCrypto encryption fallback: sending plain JSON", 'warn');
    }

    const metadata = { name: 'vault_backup.enc', parents: ['appDataFolder'], mimeType: 'application/octet-stream' };
    const form = new FormData();
    form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', new Blob([uploadBlob], { type: 'application/octet-stream' }));

    if (gDriveFileId) {
      fetch('https://www.googleapis.com/upload/drive/v3/files/' + gDriveFileId + '?uploadType=media', {
        method: 'PATCH',
        headers: { Authorization: 'Bearer ' + gDriveAccessToken, 'Content-Type': 'application/octet-stream' },
        body: uploadBlob
      })
      .then(function(res) { return res.json(); })
      .then(function() {
        logDiag("AppData file PATCH successful!");
        updateDriveBadge('☁️ AppData Backup Saved', '#00FF88');
        showWebToast('Mobile-Compatible Backup Saved!');
      });
    } else {
      fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart', {
        method: 'POST',
        headers: { Authorization: 'Bearer ' + gDriveAccessToken },
        body: form
      })
      .then(function(res) { return res.json(); })
      .then(function(file) {
        gDriveFileId = file.id;
        localStorage.setItem('secure_vault_gdrive_file_id', file.id);
        logDiag("New AppData file POST successful! ID: " + file.id);
        updateDriveBadge('☁️ AppData Backup Created', '#00FF88');
        showWebToast('New Cloud Backup Created!');
      });
    }
  }

  function updateDriveBadge(text, color) {
    const statusText = document.getElementById('driveSyncStatusText');
    if (statusText) {
      statusText.innerText = text;
      statusText.style.color = color;
    }
  }

  function signOutUser() {
    localStorage.removeItem('secure_vault_user_session');
    localStorage.removeItem('secure_vault_gdrive_file_id');
    gDriveAccessToken = null;
    gDriveFileId = null;
    lockAppView();
  }

  function clearLocalCache() {
    if (confirm('Clear local database cache?')) {
      webVault = [];
      saveWebDB(false);
      renderTables();
    }
  }

  function initDatabase() {
    const stored = localStorage.getItem('secure_vault_pro_web_db');
    if (stored) {
      try { webVault = JSON.parse(stored); } catch(e) { webVault = []; }
    } else {
      webVault = [];
      saveWebDB(false);
    }
    renderTables();
    generateWebPass();
  }

  function saveWebDB(syncDrive) {
    if (syncDrive === undefined) syncDrive = true;
    localStorage.setItem('secure_vault_pro_web_db', JSON.stringify(webVault));
    updateMetrics();
    if (syncDrive) createCloudBackupNow();
  }

  function updateMetrics() {
    document.getElementById('metricTotal').innerText = webVault.length;
    document.getElementById('metricWeb').innerText = webVault.filter(function(x) { return x.category === 'WEBSITES'; }).length;
    document.getElementById('metricApps').innerText = webVault.filter(function(x) { return x.category === 'APPS'; }).length;
    document.getElementById('metricFinance').innerText = webVault.filter(function(x) { return x.category === 'BANKING' || x.category === 'CRYPTO'; }).length;
  }

  function renderTables() {
    const dashQuery = (document.getElementById('dashSearchInput').value || '').toLowerCase();
    const vaultQuery = (document.getElementById('vaultSearchInput').value || '').toLowerCase();

    const dashBody = document.getElementById('dashTableBody');
    const dashFiltered = webVault.filter(function(x) { return x.title.toLowerCase().includes(dashQuery) || x.username.toLowerCase().includes(dashQuery); });

    dashBody.innerHTML = dashFiltered.length === 0 ? `
      <tr><td colspan="5" style="text-align:center; padding:35px; color:var(--text-body);">
        <div style="font-size:32px; margin-bottom:8px;">🔒</div>
        <div>Your Vault is Clean &amp; Empty</div>
        <div style="font-size:12px; margin-top:4px; opacity:0.8;">Click "+ Add Credential" or "Sync Android AppData" to populate your vault.</div>
      </td></tr>
    ` : dashFiltered.map(function(item) { return `
      <tr>
        <td><strong style="color:var(--text-heading);">${item.emoji || '🌐'} ${item.title}</strong></td>
        <td><span style="font-size:12px; padding:4px 10px; background:var(--surface-hover); border-radius:6px; font-weight:600;">${item.category}</span></td>
        <td>${item.username}</td>
        <td><span style="color:var(--success); font-weight:600;">Encrypted AES-256</span></td>
        <td>
          <div class="table-actions">
            <button class="tbl-btn" onclick="copyPassVal('${item.password}')">📋 Copy</button>
          </div>
        </td>
      </tr>
    `; }).join('');

    const vaultBody = document.getElementById('vaultTableBody');
    const vaultFiltered = webVault.filter(function(x) { return x.title.toLowerCase().includes(vaultQuery) || x.username.toLowerCase().includes(vaultQuery); });

    vaultBody.innerHTML = vaultFiltered.length === 0 ? `
      <tr><td colspan="5" style="text-align:center; padding:35px; color:var(--text-body);">No matching entries found in your vault.</td></tr>
    ` : vaultFiltered.map(function(item) { return `
      <tr>
        <td><strong style="color:var(--text-heading);">${item.emoji || '🌐'} ${item.title}</strong></td>
        <td><span style="font-size:12px; padding:4px 10px; background:var(--surface-hover); border-radius:6px; font-weight:600;">${item.category}</span></td>
        <td>${item.username}</td>
        <td><code style="background:var(--bg-main); padding:4px 8px; border-radius:6px; font-family:'Space Grotesk';">• • • • • • • • • •</code></td>
        <td>
          <div class="table-actions">
            <button class="tbl-btn" onclick="copyPassVal('${item.password}')">📋 Copy</button>
            <button class="tbl-btn" onclick="deleteWebEntry(${item.id})" style="color:var(--danger); border-color:var(--danger);">🗑️ Delete</button>
          </div>
        </td>
      </tr>
    `; }).join('');

    updateMetrics();
  }

  function saveWebEntry() {
    const title = document.getElementById('addTitle').value.trim();
    const username = document.getElementById('addUsername').value.trim();
    const password = document.getElementById('addPassword').value || 'Pass#' + Math.floor(Math.random()*8999+1000);
    const category = document.getElementById('addCategory').value;

    if (!title || !username) { alert('Please enter Account Title and Username'); return; }

    const emojiMap = { WEBSITES: '🌐', APPS: '📱', BANKING: '🏦', CRYPTO: '🪙' };

    webVault.unshift({
      id: Date.now(),
      title: title,
      username: username,
      password: password,
      category: category,
      emoji: emojiMap[category] || '🌐'
    });

    saveWebDB(true);
    renderTables();
    closeModal('addModal');
    document.getElementById('addTitle').value = '';
    document.getElementById('addUsername').value = '';
    document.getElementById('addPassword').value = '';
  }

  function deleteWebEntry(id) {
    webVault = webVault.filter(function(x) { return x.id !== id; });
    saveWebDB(true);
    renderTables();
  }

  function copyPassVal(val) {
    navigator.clipboard.writeText(val);
    showWebToast('Password Copied!');
  }

  function exportDataJSON() {
    const blob = new Blob([JSON.stringify(webVault, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'secure_vault_backup.json';
    a.click();
  }

  function exportDataCSV() {
    let csv = 'ID,Title,Category,Username,Password\n';
    webVault.forEach(function(item) {
      csv += '"' + item.id + '","' + item.title + '","' + item.category + '","' + item.username + '","' + item.password + '"\n';
    });
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.href = url;
    a.download = 'secure_vault_backup.csv';
    a.click();
  }

  function importData(event) {
    const file = event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(e) {
      try {
        const parsed = JSON.parse(e.target.result);
        if (Array.isArray(parsed)) {
          webVault = parsed;
          saveWebDB(true);
          renderTables();
        }
      } catch(err) { alert('Failed to parse backup file'); }
    };
    reader.readAsText(file);
  }

  function generateWebPass() {
    const len = parseInt(document.getElementById('lenSlider').value) || 18;
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+';
    let res = '';
    for (let i = 0; i < len; i++) { res += chars.charAt(Math.floor(Math.random() * chars.length)); }
    document.getElementById('webGenOutput').value = res;
  }
  function copyWebPass() {
    navigator.clipboard.writeText(document.getElementById('webGenOutput').value);
    showWebToast('Key Copied!');
  }

  function startTotpTimer() {
    setInterval(function() {
      totpTimeLeft--;
      if (totpTimeLeft <= 0) {
        totpTimeLeft = 30;
        const code = Math.floor(100000 + Math.random() * 899999).toString();
        document.getElementById('totpCodeText').innerText = code.slice(0,3) + ' ' + code.slice(3);
      }
      document.getElementById('totpTimerText').innerText = totpTimeLeft + 's';
    }, 1000);
  }
  function copyTotpVal() {
    const code = document.getElementById('totpCodeText').innerText.replace(/\s/g, '');
    navigator.clipboard.writeText(code);
    showWebToast('2FA Code Copied: ' + code);
  }

  function switchTab(name, el) {
    document.querySelectorAll('.tab-pane').forEach(function(p) { p.classList.remove('active'); });
    document.querySelectorAll('.nav-link').forEach(function(n) { n.classList.remove('active'); });
    document.querySelectorAll('.menu-item').forEach(function(m) { m.classList.remove('active'); });

    if (name === 'dashboard') {
      document.getElementById('tabDashboard').classList.add('active');
      document.getElementById('menuDashboard').classList.add('active');
    } else if (name === 'vault') {
      document.getElementById('tabVault').classList.add('active');
      document.getElementById('menuVault').classList.add('active');
    } else if (name === 'generator') {
      document.getElementById('tabGenerator').classList.add('active');
      document.getElementById('menuGen').classList.add('active');
    } else if (name === 'totp') {
      document.getElementById('tabTotp').classList.add('active');
      document.getElementById('menuTotp').classList.add('active');
    } else if (name === 'backup') {
      document.getElementById('tabBackup').classList.add('active');
      document.getElementById('menuBackup').classList.add('active');
    } else if (name === 'settings') {
      document.getElementById('tabSettings').classList.add('active');
      document.getElementById('menuSettings').classList.add('active');
    }
  }

  function toggleTheme() {
    const current = document.documentElement.getAttribute('data-theme') || 'dark';
    const next = current === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('secure_vault_pro_web_theme', next);
  }

  function openModal(id) { document.getElementById(id).classList.add('active'); }
  function closeModal(id) { document.getElementById(id).classList.remove('active'); }

  function showWebToast(msg) {
    const t = document.createElement('div');
    t.style.cssText = 'position:fixed; bottom:30px; right:30px; background:var(--surface-card); border:1px solid var(--primary); color:var(--text-heading); padding:12px 24px; border-radius:12px; font-size:14px; font-weight:600; z-index:400; box-shadow:0 10px 30px rgba(0,0,0,0.3);';
    t.innerText = msg;
    document.body.appendChild(t);
    setTimeout(function() { t.remove(); }, 2500);
  }

  document.addEventListener('DOMContentLoaded', function() {
    checkAuthSession();
    document.getElementById('dashSearchInput').addEventListener('input', renderTables);
    document.getElementById('vaultSearchInput').addEventListener('input', renderTables);
  });
